    }
    return(
        <>
        <div classNAme="Hello">
            <h1>Contact</h1>
        </div>
        <div className="form">
            <form >
                <label className="lable">Contact US</label> <br /><br/>
                <input type="text" placeholder="Enter Name BKL" required />
                <input type="email" placeholder='Email Dall bkl' required />
                <div className='selectPro'>
                    <h3>Select Product type to enqure about</h3>
